import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
export const t = (key, params = {}) => app.translator.trans(`ernestdefoe-predictions.forum.${key}`, params);
export const tx = (key, params = {}) => extractText(t(key, params));
export function predictionUrl(id) {
  return app.forum.attribute('baseUrl') + '/predictions/' + id;
}
export function percent(value) {
  return new Intl.NumberFormat(app.translator.getLocale() || undefined, {
    style: 'percent',
    maximumFractionDigits: 0
  }).format(value);
}

/** A yes/no prediction's two choices, in the reader's language (they're stored as "Yes" and "No"). */
export function optionLabel(prediction, option, index) {
  return prediction.type === 'yesno' ? tx(index === 0 ? 'card.yes' : 'card.no') : option.label;
}
export function openForm(attrs = {}) {
  app.modal.show(() => import(/* webpackChunkName: 'forum/components', webpackMode: 'lazy-once' */ './components').then(ui => ({
    default: ui.PredictionModal
  })), attrs);
}